        if $crate::hir::ResolvedResidualType::construction_is_admitted() {
            ::core::option::Option::Some($crate::hir::ResolvedResidualType(::std::boxed::Box::new(
                $value,
            )))
        } else {
            ::core::option::Option::None
        }
    }};
