                &mut scopes,
                allow_moves,
                allowed_effects,
            )?,
            frame @ (Frame::InvokeNext { .. }
            | Frame::InvokeAfter { .. }
            | Frame::RestorePublication(..)
            | Frame::Unary { .. }) => frame_phase_0(
                self,
