                            byte.is_ascii_lowercase() || byte.is_ascii_digit()
                        })
                        && bytes.last().is_some_and(|byte| {
                            byte.is_ascii_lowercase() || byte.is_ascii_digit()
                        })
                        && bytes.iter().all(|byte| {
